import 'dart:math' as math;

import 'package:flutter/material.dart';

import '../theme/theme.dart';

/// The LifeMeter mark, "One-Hand Life Clock": a paper-white dial on a cobalt
/// tile with one cobalt hand at 10:54 and a fluoro-pink "now" knob on the rim
/// where it points. It's still morning. Mirrors `assets/images/logo.svg`
/// (generated by `tool/logo.py`).
class LogoMark extends StatelessWidget {
  const LogoMark({super.key, this.size = 40, this.tile = cobalt});

  final double size;
  final Color tile;

  static const cobalt = Color(0xFF2340F5);
  static const pink = Color(0xFFFF48B0);

  @override
  Widget build(BuildContext context) {
    return Semantics(
      label: 'LifeMeter',
      image: true,
      child: SizedBox.square(
        dimension: size,
        child: CustomPaint(painter: LogoPainter(tile)),
      ),
    );
  }
}

/// Geometry shared with `tool/logo.py` (fractions of the tile side).
///
/// With [drawTile] the whole tile is painted. Without it, the glyph is drawn
/// cropped to its own bounds so it fills the box; [tile] is still used for the
/// hand and the knob's gap ring, so draw it on a background of that colour.
class LogoPainter extends CustomPainter {
  const LogoPainter(this.tile, {this.drawTile = true});

  final Color tile;
  final bool drawTile;

  static const dialR = 0.272;
  static const handW = 0.092;
  static const knobR = 0.105;
  static const gap = 0.029;
  static const knobAt = 1.07;
  static const overlap = 0.020;
  static const angle = (10 + 54 / 60) / 12 * 2 * math.pi; // 10:54
  static const handL = dialR * knobAt - knobR - gap - handW / 2 + overlap;
  // The knob centre sits on a pixel centre at 16 and 48 px.
  static const knobX = 5.5 / 16;
  static const knobY = 4.5 / 16;
  // Square crop around the visible glyph, on the 1024 grid.
  static const cropX = 196.4 / 1024;
  static const cropY = 180.4 / 1024;
  static const cropS = 636 / 1024;

  @override
  void paint(Canvas canvas, Size size) {
    final s = size.shortestSide;
    if (drawTile) {
      canvas.drawRRect(
        RRect.fromRectAndRadius(
          Offset.zero & Size.square(s),
          Radius.circular(s * 0.24),
        ),
        Paint()..color = tile,
      );
    } else {
      // Scale so the glyph's crop box fills the square.
      canvas.save();
      canvas.scale(1 / cropS);
      canvas.translate(-cropX * s, -cropY * s);
    }
    final dir = Offset(math.sin(angle), -math.cos(angle));
    final knob = Offset(knobX * s, knobY * s);
    final dial = knob - dir * (dialR * knobAt * s);
    final cut = Paint()..color = tile;
    canvas.drawCircle(dial, dialR * s, Paint()..color = Colors.white);
    canvas.drawLine(
      dial,
      dial + dir * (handL * s),
      Paint()
        ..color = tile
        ..strokeWidth = handW * s
        ..strokeCap = StrokeCap.round,
    );
    canvas.drawCircle(knob, (knobR + gap) * s, cut);
    canvas.drawCircle(knob, knobR * s, Paint()..color = LogoMark.pink);
    if (!drawTile) canvas.restore();
  }

  @override
  bool shouldRepaint(LogoPainter old) =>
      old.tile != tile || old.drawTile != drawTile;
}

/// Mark plus "LifeMeter" in Schibsted 700.
class Wordmark extends StatelessWidget {
  const Wordmark({super.key, this.size = 20, this.color, this.mark = true});

  final double size;
  final Color? color;
  final bool mark;

  @override
  Widget build(BuildContext context) {
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        if (mark) ...[
          LogoMark(size: size * 1.35),
          SizedBox(width: size * 0.45),
        ],
        Text(
          'LifeMeter',
          style: context.type.title.copyWith(
            fontSize: size,
            letterSpacing: -0.4,
            color: color ?? context.lm.ink,
          ),
        ),
      ],
    );
  }
}
